    async def retrieve(
        self,
        authorization_id: str,
        *,
        extra_headers: Optional[Headers] = None,
        extra_query: Optional[Query] = None,
        extra_body: Optional[Body] = None,
        timeout: Union[float, httpx2.Timeout, None, NotGiven] = not_given,
    ) -> _models.MCPOAuthAuthorization:
        """Get an MCP OAuth authorization. Returns an MCP OAuth authorization, to poll while the user signs in: `pending` until the callback has been processed (also while the code is being exchanged), then `completed` with `credential_id` or `failed` with `error_code`; a flow still pending 10 minutes after it was created reads as `expired`. Any caller that may read the workspace where the flow was started can read it, not only the user who started it. An unknown ID, or a flow of another workspace, is a 404 `not_found_error` without an `error.code`. Reading changes nothing. **Authorization:** Organization API key (`x-api-key: bma_org_v1_…`), personal access token (`Authorization: Bearer bma_pat_v1_…`), signed-in user token or dashboard session; user credentials name the organization with `bma-organization-id`. The request acts in one workspace: the one named by `bma-workspace-id`, which may be left out when the credential resolves to a single workspace (the workspace an API key is bound to, or a member's only workspace). Any workspace role (admin, developer, operator, viewer) may call it; organization owners and admins act as workspace admins in every workspace of their organization. _models.Machine, executor and session credentials are refused. **Limits:** - An authorization stays pending for at most 10 minutes after it was created, then reads as `expired`. - Rate limit: one request of the organization's read budget ([Rate limits](https://docs.beeos.ai/guides/limits)). **Errors** (besides the [common errors](https://docs.beeos.ai/api-reference/errors) (401 authentication, 429 `rate_limited`, 500)): | Status | `error.type` | `error.code` | Cause | Fix | | --- | --- | --- | --- | --- | | 400 | `invalid_request_error` | `organization_required` | A personal access token or user token names no organization with `bma-organization-id`. | Correct the request as the message describes and send it again; the same request will keep failing. | | 400 | `invalid_request_error` | `project_required` | The credential can use several workspaces and the request names none with `bma-workspace-id`. | Correct the request as the message describes and send it again; the same request will keep failing. | | 400 | `invalid_request_error` | `workspace_id_conflict` | `bma-workspace-id` and `anthropic-workspace-id` name different workspaces. | Correct the request as the message describes and send it again; the same request will keep failing. | | 403 | `permission_error` | `permission_denied` | The credential is neither an organization API key nor a user credential (for example a machine, executor or session token). | Use a credential with the required role or access; retrying with the same credential will not help. |"""
        if not authorization_id:
            raise ValueError(f"Expected a non-empty value for `authorization_id` but received {authorization_id!r}")
        return await self._get(
            path_template("/v1/mcp_oauth_authorizations/{authorization_id}", authorization_id=authorization_id),
            options=make_request_options(
                extra_headers=extra_headers, extra_query=extra_query, extra_body=extra_body, timeout=timeout
            ),
            cast_to=_models.MCPOAuthAuthorization,
        )

    async def complete(
        self,
        *,
        state: str,
        code: Union[str, Omit] = omit,
        error: Union[str, Omit] = omit,
        error_description: Union[str, Omit] = omit,
        iss: Union[str, Omit] = omit,
        extra_headers: Optional[Headers] = None,
        extra_query: Optional[Query] = None,
        extra_body: Optional[Body] = None,
        timeout: Union[float, httpx2.Timeout, None, NotGiven] = not_given,
    ) -> _models.MCPOAuthAuthorization:
        """Complete an MCP OAuth authorization. Completes an MCP OAuth authorization with the parameters the authorization server put on its redirect to the callback page (`state`, and `code` or `error`). BMA finds the flow by its single-use `state`, checks the response (an `error`, a missing `code`, or a missing or mismatched `iss` fails the flow), redeems the code with the flow's PKCE verifier and stores the tokens in the flow's vault. The answer is the finished flow: `completed` with `credential_id`, or `failed` with `error_code`; a failed exchange is a 200, not an error. Only the user who started the flow, in the same workspace, may complete it: any other caller spends the flow (it becomes `failed` with `initiator_mismatch`) and gets a 403. An unknown, already used or expired `state` is a 404 `not_found_error` without an `error.code`; a body that is not a JSON object of these fields, or has no `state`, is a 400 `invalid_request_error` without an `error.code`. The call cannot be repeated: the `state` works once. **Authorization:** The user who started the flow, with a personal access token (`Authorization: Bearer bma_pat_v1_…`), signed-in user token or dashboard session naming the organization with `bma-organization-id`, in the workspace the flow was started in (`bma-workspace-id` unless the user has a single workspace). The user's workspace role must be admin or developer (organization owners and admins act as workspace admins in every workspace of their organization). Any other caller that has such a role, an organization API key included, spends the flow. **Limits:** - Request body: at most 16 KiB (a larger body is a 400). - The callback must arrive within 10 minutes of the authorization's creation. - Rate limit: one request of the organization's write budget ([Rate limits](https://docs.beeos.ai/guides/limits)). **Errors** (besides the [common errors](https://docs.beeos.ai/api-reference/errors) (401 authentication, 429 `rate_limited`, 500)): | Status | `error.type` | `error.code` | Cause | Fix | | --- | --- | --- | --- | --- | | 400 | `invalid_request_error` | `organization_required` | A personal access token or user token names no organization with `bma-organization-id`. | Correct the request as the message describes and send it again; the same request will keep failing. | | 400 | `invalid_request_error` | `project_required` | The credential can use several workspaces and the request names none with `bma-workspace-id`. | Correct the request as the message describes and send it again; the same request will keep failing. | | 400 | `invalid_request_error` | `workspace_id_conflict` | `bma-workspace-id` and `anthropic-workspace-id` name different workspaces. | Correct the request as the message describes and send it again; the same request will keep failing. | | 403 | `permission_error` | `mcp_oauth_initiator_mismatch` | The caller is not the user who started the flow, or calls in another workspace; the flow is now failed. | Start the authorization again from the application. | | 403 | `permission_error` | `permission_denied` | The caller's workspace role is operator or viewer, or the credential is neither an organization API key nor a user credential. | Use a credential with the required role or access; retrying with the same credential will not help. |"""
